Rule.Source:
// MNB HR Identity Mapping for employeeType
// Maps HR employeeType/userType to identity warehouse employment type with validation

String employeeType = (String)link.getAttribute("employeeType");
String userType = (String)link.getAttribute("userType");

// Use employeeType if available, otherwise fall back to userType
String employmentType = employeeType != null ? employeeType : userType;

if (employmentType != null && !employmentType.isEmpty()) {
    employmentType = employmentType.trim();

    // Validate against allowed employment types
    if (employmentType.equals("Employee") || employmentType.equals("Contractor")) {
        return employmentType;
    }

    // Normalize variations of "Employee"
    if (employmentType.equalsIgnoreCase("Staff") || employmentType.equalsIgnoreCase("Worker") ||
        employmentType.equalsIgnoreCase("Worker Bee")) {
        return "Employee";
    }

    // Normalize variations of "Contractor"
    if (employmentType.equalsIgnoreCase("Contract") || employmentType.equalsIgnoreCase("Temp") ||
        employmentType.equalsIgnoreCase("Temporary")) {
        return "Contractor";
    }

    // Log unrecognized employment types for investigation
    log.warn("Unrecognized employment type "; " from MNB-HR for identity " + identity.getName() + ": " + employmentType);

    // Default to "Employee" for unrecognized types
    return "Employee";
}

return null;
